#!/usr/bin/env node
/**
 * Render the Homebrew formula from homebrew/llmctrlx.rb.template.
 *
 * The tap's formulae are all generated (see davidcrumpton/homebrew-tap README:
 * "Do not edit them by hand"), so llmctrlx follows the same rule: the release
 * workflow renders this file from the checksums it just published and pushes it.
 * That keeps the formula from drifting out of sync with the release assets.
 *
 * Usage:
 *   node scripts/render-formula.mjs --version 0.8.37 --sums <dir> --out <file>
 *
 * <dir> must contain the published `*.tar.gz.sha256` files (or bare `*.sha256`
 * files) for the four platforms. Any missing platform is an error: shipping a
 * formula with a stale or blank checksum fails at install time on the user's
 * machine, which is far worse than failing here.
 */
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const PLATFORMS = {
  'macos-arm64': 'SHA256_MACOS_ARM64',
  'macos-x64': 'SHA256_MACOS_X64',
  'linux-arm64': 'SHA256_LINUX_ARM64',
  'linux-x64': 'SHA256_LINUX_X64',
};

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i];
    if (!key?.startsWith('--')) throw new Error(`unexpected argument: ${key}`);
    args[key.slice(2)] = argv[i + 1];
  }
  return args;
}

const { version, sums, out } = parseArgs(process.argv.slice(2));
if (!version || !sums || !out) {
  console.error('usage: render-formula.mjs --version <v> --sums <dir> --out <file>');
  process.exit(2);
}

// Collect every checksum file, keyed by the platform in its filename.
const found = {};
for (const file of readdirSync(sums)) {
  if (!file.endsWith('.sha256')) continue;
  const text = readFileSync(join(sums, file), 'utf8').trim();
  // `<hash>  <filename>` (sha256sum) or `<hash> *<filename>` (shasum -b).
  const match = /^([0-9a-f]{64})\s+\*?(\S+)$/.exec(text);
  if (!match) {
    console.error(`render-formula: ${file} is not a sha256 file: ${text}`);
    process.exit(1);
  }
  const [, hash, target] = match;
  for (const platform of Object.keys(PLATFORMS)) {
    if (target.includes(platform)) found[platform] = hash;
  }
}

const missing = Object.keys(PLATFORMS).filter((p) => !found[p]);
if (missing.length > 0) {
  console.error(`render-formula: missing checksums for ${missing.join(', ')} in ${sums}`);
  process.exit(1);
}

let formula = readFileSync(
  new URL('../homebrew/llmctrlx.rb.template', import.meta.url),
  'utf8',
);

// Replace the template's own explanatory header with a "generated" one, so the
// file that lands in the tap is never mistaken for something to edit by hand.
const classAt = formula.indexOf('class ');
if (classAt === -1) {
  console.error('render-formula: template has no `class` declaration');
  process.exit(1);
}
formula =
  `# This file was generated by scripts/render-formula.mjs from\n` +
  `# homebrew/llmctrlx.rb.template in davidcrumpton/llm-control-engine. DO NOT EDIT:\n` +
  `# it is rewritten on every release. Report issues in that repository.\n` +
  `#\n` +
  `# Version ${version}. Checksums are those published with the release.\n\n` +
  formula.slice(classAt);

formula = formula.replaceAll('{{VERSION}}', version);
for (const [platform, placeholder] of Object.entries(PLATFORMS)) {
  formula = formula.replaceAll(`{{${placeholder}}}`, found[platform]);
}

// A leftover placeholder would ship a formula Homebrew cannot parse.
const leftover = formula.match(/\{\{[A-Z0-9_]+\}\}/g);
if (leftover) {
  console.error(`render-formula: unsubstituted placeholders: ${[...new Set(leftover)].join(', ')}`);
  process.exit(1);
}

// The release workflow renders to Formula/llmctrlx.rb, which is a directory that
// exists in the tap but not in this repository's checkout — creating it here is
// what stops a clean runner from dying on ENOENT.
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, formula);
console.log(`render-formula: wrote ${out} for ${version}`);
for (const platform of Object.keys(PLATFORMS)) {
  console.log(`  ${platform.padEnd(12)} ${found[platform]}`);
}
